export const meta = {
  name: 'driver-model-full-audit',
  description: '并行深读驾驶员模型项目全部日志/实验/工作树，提取难题、已试方法、错误思路与数据利用情况',
  phases: [
    { title: 'Read', detail: '10 个并行读取者覆盖状态日志、任务队列、基线、报告、Gate0 工作树、数据资产' },
    { title: 'Critic', detail: '完整性检查：还有哪些关键材料没读到' },
  ],
}

const FINDINGS = {
  type: 'object',
  required: ['scope', 'latest_status', 'problems', 'methods_tried', 'wrong_paths', 'data_assets', 'recommendations'],
  properties: {
    scope: { type: 'string', description: '本 agent 负责的范围' },
    latest_status: { type: 'string', description: '该范围内最新状态（带日期）' },
    problems: { type: 'array', items: { type: 'object', required: ['problem'], properties: { problem: { type: 'string' }, evidence: { type: 'string', description: '证据：文件+具体数字' } } } },
    methods_tried: { type: 'array', items: { type: 'object', required: ['method', 'result'], properties: { method: { type: 'string' }, result: { type: 'string', description: '结果，尽量带指标数字' }, verdict: { type: 'string', description: '有效/无效/未定，以及为什么' } } } },
    wrong_paths: { type: 'array', items: { type: 'object', required: ['path'], properties: { path: { type: 'string', description: '被证明错误或放弃的思路' }, why: { type: 'string' } } } },
    data_assets: { type: 'array', items: { type: 'object', required: ['asset'], properties: { asset: { type: 'string', description: '数据资产（模态/数据集/样本表）' }, status: { type: 'string', description: '处理状态、样本量' }, utilization: { type: 'string', description: '目前是否被模型用上、为何没用上' } } } },
    recommendations: { type: 'array', items: { type: 'string' }, description: '该范围材料中已经写明的下一步建议' },
    key_files: { type: 'array', items: { type: 'string' } },
  },
}

const COMMON = `你是资深算法/数据分析研究员，正在审计一个"极限工况下驾驶员转向反应预测"研究项目（多模态：车辆信号/道路/生理/EEG，仿真驾驶实验，约20+被试，200Hz，历史窗3s预测未来2s方向盘轨迹）。
你的任务：只读文件，不修改任何东西。仔细阅读指定材料（长文件要分段读完或用 Grep 定位关键节），提取：
1) 该范围暴露的核心难题/瓶颈（带证据和数字）；
2) 已尝试过的方法及其结果（带 RMSE/错侧率等具体指标）；
3) 被证明错误、无效或已放弃的思路（明确写为什么）;
4) 数据资产盘点：有什么数据、处理到什么程度、模型是否用上了；
5) 材料中已写明的下一步建议。
注意区分"最新状态"和"历史状态"（该项目 2026-05 是旧流程，2026-07 的 Gate 0 是最新路线）。所有结论必须来自你真实读到的内容，不许编造。用中文返回。`

phase('Read')

const readers = [
  {
    label: 'status-history',
    prompt: `${COMMON}
你的范围：主状态日志。完整读完 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\PROJECT_STATUS_CN.md（共约1672行，必须分多次 Read 读完全文，尤其是文件后半部分的更早历史：Stage 1-7 车辆-only 基线、Transformer、多假设、风格、生理阻塞逻辑）。梳理整个项目按时间线的：阶段划分、每阶段的难题、试过的方法与指标、gate 决策（哪些被判 no_upgrade / no-go / blocked）。`,
  },
  {
    label: 'task-queue-scope-goal',
    prompt: `${COMMON}
你的范围：任务队列与研究目标定义。读完：
1) F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\TASK_QUEUE_CN.md（约2495行，分多次读完，重点是文件前部最新条目 + 后部早期条目里反复出现的阻塞项）
2) F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\00_rebuild_scope_cn.md
3) F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\R2E_STEERING_LONG_GOAL_CN.md
4) F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\STAGE00_01_COMPLETION_AUDIT_CN.md（若存在）
提取：为什么要从原始数据重建（旧流程有什么问题）、长期研究目标是什么、哪些任务被长期阻塞、反复出现的红线规则。`,
  },
  {
    label: 'artifact-index-reports',
    prompt: `${COMMON}
你的范围：产物索引与人类可读报告。
1) 读 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\ARTIFACT_INDEX_CN.md
2) 用 Glob 列出 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\09_reports 下所有 .md，按修改时间选最新的 8-12 份读（优先 2026-06/07 的、user_summary 类的），历史 5 月的挑代表性 gate/决策类读 3-5 份。
提取：最新报告里的结论、指标、遗留问题；报告体系里反复强调的失败模式（错侧、幅值不足、尾段误差等）。`,
  },
  {
    label: 'baselines-experiments',
    prompt: `${COMMON}
你的范围：模型实验产物。
1) 用 Glob/Bash 列出 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\03_baselines 下的子目录（按名字/时间排序），挑最新的 5-8 个实验目录，读其中的 run_summary / metrics / gate 表 / *.md。
2) 同样处理 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\07_multihypothesis（挑最新 3-5 个 stage 目录的 gate 表和汇总表）。
3) 同样处理 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\06_structured_models（若存在）。
提取：各实验的模型类型、输入特征、指标（RMSE/错侧率/幅值不足/尾段）、和 RBF/KNN 主参照的对比、gate 结论。重点回答：哪些模型路线试了但没超过简单基线。`,
  },
  {
    label: 'gate0-main-checkout',
    prompt: `${COMMON}
你的范围：主检出目录里的 Gate 0 最新路线与近期日志。
1) 用 Glob 列出并读 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\10_gate0_professional_reprocessing_20260710 下的所有 .md / 主要文件。
2) 读 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\00_REFOUNDATION_20260710 下的登记材料。
3) 读 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\00_project_notes\\reports_20260706 下的报告。
4) 用 Glob 找 00_project_notes\\daily_logs 下最新的 5-8 个日志读。
5) 读 00_project_notes\\SERVER_RUNS_CN.md（若存在）。
提取：Gate 0 是什么、为什么 7 月要专业重处理、目前进展到哪、暴露了什么新问题。`,
  },
  {
    label: 'worktree-g0-wp3',
    prompt: `${COMMON}
你的范围：独立工作树 F:\\g0_wp3。
1) 先用 Bash (git -C F:\\g0_wp3 log --oneline -20; git -C F:\\g0_wp3 status) 看这个工作树最近在干什么。
2) 用 Glob 找其中最新修改的 .md 报告/状态文件（重点找 10_gate0_professional_reprocessing_20260710、00_project_notes、09_reports 相关），读最新的 6-10 份。
3) 找到该 workpackage 的目标定义、当前进展、实验结果和遗留问题。若目录不存在或为空，如实报告。`,
  },
  {
    label: 'worktree-g0-wp6-target1s',
    prompt: `${COMMON}
你的范围：独立工作树 F:\\g0_wp6 与 F:\\target1s。
对每个目录：
1) 用 Bash (git -C <dir> log --oneline -20) 看最近提交。
2) 用 Glob 找最新修改的 .md 状态/报告文件，各读最新 5-8 份。
提取：各工作包的目标、当前进展、实验结果（带指标）、遗留问题。特别注意 target1s 可能是"预测目标改为1s"之类的实验路线，弄清它的动机和结论。若目录不存在，如实报告。`,
  },
  {
    label: 'worktree-g0-main',
    prompt: `${COMMON}
你的范围：独立工作树 F:\\g0\\05_rebuild_from_raw_20260511\\10_gate0_professional_reprocessing_20260710（以及 F:\\g0 整体）。
1) 用 Bash (git -C F:\\g0 log --oneline -20) 看最近提交。
2) 用 Glob 在 F:\\g0\\05_rebuild_from_raw_20260511\\10_gate0_professional_reprocessing_20260710 下找所有 .md 和主要表格/脚本，按修改时间读最新的 8-12 份。
提取：Gate 0 专业重处理在这个工作树里的完整设计（WP 划分、每个 WP 目标）、已完成部分、实验结果、遗留问题。若目录不存在，如实报告。`,
  },
  {
    label: 'old-logs-decisions',
    prompt: `${COMMON}
你的范围：旧版全局日志与决策记录。
1) 读 F:\\data_set_process\\data_process\\04_project_logs\\reports\\progress\\decision_log.md
2) 读 F:\\data_set_process\\data_process\\04_project_logs\\reports\\progress\\experiment_registry.md
3) 读 F:\\data_set_process\\data_process\\04_project_logs\\references\\current-state.md
4) F:\\data_set_process\\data_process\\04_project_logs\\reports\\project_progress_master.md 很长的话只读文件头部的当前状态汇总/索引部分（前300行）+ 最后300行。
5) 用 Glob 看 04_project_logs\\reports\\progress\\daily 下最新 3-5 个日志。
提取：项目重大路线决策及其依据（尤其"为什么放弃旧流程 v14/事件数据集/Transformer v5.8 那条线"）、历史实验注册表里的成败记录。`,
  },
  {
    label: 'data-assets-modalities',
    prompt: `${COMMON}
你的范围：数据资产与模态处理现状。
1) 用 Glob/Bash 列 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511\\03_processed_datasets 的目录结构，读其中 README/manifest/说明 .md。
2) 同样处理 06_physio_processing、07_eeg_processing、08_multimodal_processing（各读最新报告/说明 3-5 份）。
3) 读 01_audit 下最新的审计报告 3-5 份。
4) 若上述目录内容稀少，用 Glob 在 F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511 下找 *physio*/*eeg*/*multimodal* 相关 .md。
提取：每个模态（车辆/道路/生理/EEG/驾驶风格）的数据量、被试覆盖、处理管线状态、质量问题、是否已进入任何模型、被阻塞的原因。这是回答"如何充分利用数据"的关键素材。`,
  },
