const results = await parallel(readers.map(r => () =>
  agent(r.prompt, { label: r.label, phase: 'Read', schema: FINDINGS })
))

const named = results.map((res, i) => ({ reader: readers[i].label, findings: res })).filter(x => x.findings)

phase('Critic')
const criticSummary = named.map(x => `## ${x.reader}\n最新状态: ${x.findings.latest_status}\n难题数: ${x.findings.problems.length}, 已试方法数: ${x.findings.methods_tried.length}, 错误思路数: ${x.findings.wrong_paths.length}`).join('\n')
const critic = await agent(`${COMMON}
以下是 10 个并行审计员各自覆盖范围的摘要：
${criticSummary}

你的任务：完整性检查。快速核查项目目录（F:\\data_set_process\\data_process\\05_rebuild_from_raw_20260511 及 F:\\g0_wp3、F:\\g0_wp6、F:\\target1s、F:\\g0），判断是否有重要材料/最新实验没有被覆盖到（例如：最新的训练 run、某个 WP 的最终报告、生理或 EEG 的最新处理结果、02_samples 里的人工复核结论）。用 Glob 按修改时间找 2026-06 以后的 .md/.json 关键文件抽查 5-10 份。返回：遗漏点清单 + 每个遗漏点的关键内容摘要。`,
  { label: 'completeness-critic', phase: 'Critic', schema: {
    type: 'object', required: ['gaps'],
    properties: { gaps: { type: 'array', items: { type: 'object', required: ['gap', 'summary'], properties: { gap: { type: 'string' }, summary: { type: 'string' }, key_files: { type: 'array', items: { type: 'string' } } } } } },
  } })

return { readers: named, critic }

